toolCalls.args:
{"command":"$f = Get-Content .\input\session.jsonl
foreach ($line in $f) {
  try { $o = $line | ConvertFrom-Json } catch { continue }
  $p = $o.payload
  if ($o.type -eq 'response_item' -and $p.type -eq 'custom_tool_call') {
    $in = $p.input
    if ($in -is [string]) { $txt = $in } else { $txt = ($in | ConvertTo-Json -Compress -Depth 6) }
    Write-Output ("=== ord " + $o.ordinal + " call " + $p.call_id + " name=" + $p.name + " status=" + $p.status)
    Write-Output ($txt.Substring(0, [Math]::Min($txt.Length, 1200)))
    Write-Output ""
  }
}"}

{"command":"$f = Get-Content .\input\session.jsonl
# capture custom_tool_call_output entries and summarize
$out = @()
for ($i=0; $i -lt $f.Count; $i++) {
  $line = $f[$i]
  try { $o = $line | ConvertFrom-Json } catch { continue }
  if ($o.type -eq 'response_item' -and $o.payload.type -eq 'custom_tool_call_output') {
    $txt = ($o.payload.output | Out-String)
    # find preceding tool call id by scanning backwards for custom_tool_call with same call_id
    $cid = $o.payload.call_id
    for ($j=$i-1; $j -ge 0; $j--) {
      try { $q = $f[$j] | ConvertFrom-Json } catch { continue }
      if ($q.type -eq 'response_item' -and $q.payload.type -eq 'custom_tool_call' -and $q.payload.call_id -eq $cid) { break }
    }
    $out += [pscustomobject]@{ ord=$o.ordinal; call=$cid }
  }
}
Write-Output ("tool outputs: " + $out.Count)"}

{"command":"$f = Get-Content .\input\session.jsonl
$hits = $f | Select-String -Pattern 'MarginApp|marginApiClient|RecentSessions|SessionDetail|margin.css' 
foreach ($h in $hits) {
  $ln = $h.Line
  $i = $ln.IndexOf('"input"')
  Write-Output ("ord? line starts: " + $ln.Substring(0, [Math]::Min($ln.Length, 600)))
  Write-Output "----"
}"}

{"command":"$f = Get-Content .\input\session.jsonl
$targets = @('call_Trz4h084DxYo35nkXVjcVpcK','call_N9wTIdjoqk0MkmUwN2osWW1B','call_kwPXmhdsAvi77SJiX5HrUfNI','call_t6wXiOXrCPrHoOdJUBYyEUXI')
foreach ($line in $f) {
  try { $o = $line | ConvertFrom-Json } catch { continue }
  if ($o.type -eq 'response_item' -and $o.payload.type -eq 'custom_tool_call_output' -and $targets -contains $o.payload.call_id) {
    Write-Output ("########## call " + $o.payload.call_id + " ord " + $o.ordinal)
    $all = ''
    foreach ($t in $o.payload.output) { if ($t.text) { $all += $t.text } }
    Write-Output ("LEN=" + $all.Length)
    if ($all.Length -gt 2600) { Write-Output ($all.Substring($all.Length-2600)) } else { Write-Output $all }
  }
}"}

{"command":"$f = Get-Content .\input\session.jsonl
foreach ($line in $f) {
  try { $o = $line | ConvertFrom-Json } catch { continue }
  if ($o.type -eq 'response_item' -and $o.payload.type -eq 'custom_tool_call_output' -and $o.payload.call_id -eq 'call_Trz4h084DxYo35nkXVjcVpcK') {
    $all = ''
    foreach ($t in $o.payload.output) { if ($t.text) { $all += $t.text } }
    $lines = $all -split "`n"
    Write-Output ("lines: " + $lines.Count)
    $lines | Select-String -Pattern 'not ok|✖|fail' | Select-Object -First 40
  }
}"}

